    "formatName": "mov,mp4 (AVFoundation adapter)"
  },
  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 1.28,
        "text": "20万粉丝了"
      },
      {
        "start": 1.28,
        "end": 3.6,
        "text": "我年底50万粉丝目标不会称能实现吧"
      },
      {
        "start": 3.6,
        "end": 4.52,
        "text": "在这个时间节点呢"
      },
      {
        "start": 4.52,
        "end": 5.8,
        "text": "我想做一些视频"
      },
      {
        "start": 5.8,
        "end": 7.44,
        "text": "再也跟大家好好地分享一下"
      },
      {
        "start": 7.44,
        "end": 9.08,
        "text": "我自己做自媒体的这个经验"
      },
      {
        "start": 9.08,
        "end": 10.52,
        "text": "那今天主要要讲的是什么呢"
      },
      {
        "start": 10.52,
        "end": 11.16,
        "text": "讲的就是"
      },
      {
        "start": 11.16,
        "end": 13.08,
        "text": "我是如何通过观测"
      },
      {
        "start": 13.08,
        "end": 14.68,
        "text": "一些关键的数据"
      },
      {
        "start": 14.68,
        "end": 16.68,
        "text": "和一些技巧来帮助我提升"
      },
      {
        "start": 16.68,
        "end": 18.36,
        "text": "我视频的流量和播放量的"
      },
      {
        "start": 18.36,
        "end": 19.2,
        "text": "因为我发现"
      },
      {
        "start": 19.2,
        "end": 20.76,
        "text": "是一场很多人现在在看数据的时候"
      },
      {
        "start": 20.76,
        "end": 22,
        "text": "他的制度体系或者说"
      },
      {
        "start": 22,
        "end": 23.92,
        "text": "他的认知还挺有在好几年前的状态"
      },
      {
        "start": 23.92,
        "end": 25.28,
        "text": "什么5秒完播"
      },
      {
        "start": 25.28,
        "end": 26.12,
        "text": "2秒跳出"
      },
      {
        "start": 26.12,
        "end": 27.04,
        "text": "叫改开头啊"
      },
      {
        "start": 27.04,
        "end": 27.92,
        "text": "什么亂七八糟"
      },
      {
        "start": 27.92,
        "end": 28.68,
        "text": "但谁想这一套"
      },
      {
        "start": 28.68,
        "end": 30.32,
        "text": "就是什么目前已经是过时的"
      },
      {
        "start": 30.32,
        "end": 32.36,
        "text": "然后再加上在我这个起号的过程中"
      },
      {
        "start": 32.36,
        "end": 33.92,
        "text": "我也注意到很多的朋友"
      },
      {
        "start": 33.92,
        "end": 35.16,
        "text": "因为看到我的成长"
      },
      {
        "start": 35.16,
        "end": 36.96,
        "text": "然后自己也踏上了自媒体的这条路"
      },
      {
        "start": 36.96,
        "end": 38.36,
        "text": "所以我今天就来分享一下"
      },
      {
        "start": 38.36,
        "end": 40.76,
        "text": "我个人的最新的一些经验"
      },
      {
        "start": 40.76,
        "end": 42.24,
        "text": "ok让我们开始今天的节目"
      },
      {
        "start": 42.24,
        "end": 42.88,
        "text": "第一个呢"
      },
      {
        "start": 42.88,
        "end": 44.56,
        "text": "就是关于抖音的这些数据指标"
      },
      {
        "start": 44.56,
        "end": 45.56,
        "text": "实际上的今天的抖音"
      },
      {
        "start": 45.56,
        "end": 47.08,
        "text": "已经和过去完全不一样了"
      },
      {
        "start": 47.08,
        "end": 49.32,
        "text": "他现在追求的并不是短瓶快的内容"
      },
      {
        "start": 49.32,
        "end": 51.68,
        "text": "而是不停的在扶持深度的"
      },
      {
        "start": 51.68,
        "end": 53.48,
        "text": "中长视频的内容创作者"
      },
      {
        "start": 53.48,
        "end": 54.44,
        "text": "特别典型的一个案例"
      },
      {
        "start": 54.44,
        "end": 55.4,
        "text": "就是大家这一两年有没有"
      },
      {
        "start": 55.4,
        "end": 56,
        "text": "刷到一个叫"
      },
      {
        "start": 56,
        "end": 56.84,
        "text": "米三汉的播出"
      },
      {
        "start": 56.84,
        "end": 58.96,
        "text": "讲的红龙梦他这个很长"
      },
      {
        "start": 58.96,
        "end": 60.32,
        "text": "六个半小时的视频"
      },
      {
        "start": 60.32,
        "end": 61.24,
        "text": "我是分段"
      },
      {
        "start": 61.24,
        "end": 63,
        "text": "然后分了好几天再给大家看"
      },
      {
        "start": 63,
        "end": 65.36,
        "text": "1500多万的点赞"
      },
      {
        "start": 65.36,
        "end": 67.08,
        "text": "应该说在短视频平台上"
      },
      {
        "start": 67.08,
        "end": 68.44,
        "text": "确实是一个奇迹"
      },
      {
        "start": 68.44,
        "end": 69.68,
        "text": "那像这类的视频"
      },
      {
        "start": 69.68,
        "end": 71.68,
        "text": "按照大家过去的固有任职"
      },
      {
        "start": 71.68,
        "end": 72.44,
        "text": "就是他的无谣"
      },
      {
        "start": 72.44,
        "end": 73.56,
        "text": "管部率要达到多少"
      },
      {
        "start": 73.56,
        "end": 75.03999999999999,
        "text": "他的总管部率要达到多少"
      },
      {
        "start": 75.03999999999999,
        "end": 76.8,
        "text": "他两秒跳出要达到多少"
      },
      {
        "start": 76.8,
        "end": 77.92,
        "text": "那这种超长的视频"
      },
      {
        "start": 77.92,
        "end": 78.6,
        "text": "在这种数据上"
      },
      {
        "start": 78.6,
        "end": 80.24,
        "text": "绝对是不合格的"
      },
      {
        "start": 80.24,
        "end": 82.36,
        "text": "但是为什么太能获得这么高的流量呢"
      },
      {
        "start": 82.36,
        "end": 84.03999999999999,
        "text": "那就说明要在今天这个时间的节点"
      },
      {
        "start": 84.03999999999999,
        "end": 86,
        "text": "抖音对于优质内容的判定"
      },
      {
        "start": 86,
        "end": 87.4,
        "text": "和推流已经产生了"
      },
      {
        "start": 87.4,
        "end": 88.6,
        "text": "非常大的一个电话"
      },
      {
        "start": 88.6,
        "end": 90.32,
        "text": "那现在在我心目中"
      },
      {
        "start": 90.32,
        "end": 92.16,
        "text": "有哪些指标是非常重要的呢"
      },
      {
        "start": 92.16,
        "end": 93.72,
        "text": "首先在新手起号"
      },
      {
        "start": 93.72,
        "end": 95.44,
        "text": "其实有两个关键的指标"
      },
      {
        "start": 95.44,
        "end": 96.68,
        "text": "是我用来判断"
      },
      {
        "start": 96.68,
        "end": 97.52000000000001,
        "text": "然后这个账号"
      },
      {
        "start": 97.52000000000001,
        "end": 100.2,
        "text": "或者说这条视频的流量是否是正常的"
      },
      {
        "start": 100.2,
        "end": 101.12,
        "text": "因为我发现很多人"
      },
      {
        "start": 101.12,
        "end": 102.64,
        "text": "他这个作品上的这个账号"
      },
      {
        "start": 102.64,
        "end": 104.36,
        "text": "东明秘密已经是被限流的状态了"
      },
      {
        "start": 104.36,
        "end": 106.4,
        "text": "但他还傻乎的日更一堆视频"
      },
      {
        "start": 106.4,
        "end": 107.16,
        "text": "然后去问问说"
      },
      {
        "start": 107.16,
        "end": 108.24000000000001,
        "text": "为什么我这个流量起不来"
      },
      {
        "start": 108.24000000000001,
        "end": 109.8,
        "text": "实际上根本就是回归啊"
      },
      {
        "start": 109.8,
        "end": 111.03999999999999,
        "text": "那哪两个指标可以看出来"
      },
      {
        "start": 111.03999999999999,
        "end": 112.6,
        "text": "一个作品或者账号有没有问题呢"
      },
      {
        "start": 112.6,
        "end": 115.8,
        "text": "第一个就是推一件业的流量占品"
      },
      {
        "start": 115.8,
        "end": 118,
        "text": "就是说你所有的流量来源里面"
      },
      {
        "start": 118,
        "end": 120.72,
        "text": "有多少是来自于系统的推流"
      },
      {
        "start": 120.72,
        "end": 122.4,
        "text": "也就是推键业的"
      },
      {
        "start": 122.4,
        "end": 124.8,
        "text": "这个指标要高于80%"
      },
      {
        "start": 124.8,
        "end": 126.8,
        "text": "甚至高于85%才是正常的"
      },
      {
        "start": 126.8,
        "end": 128,
        "text": "如果是一个特别优质的"
      },
      {
        "start": 128,
        "end": 129.2,
        "text": "流量特别高的作品"
      },
      {
        "start": 129.2,
        "end": 131.6,
        "text": "那推进业的占比通常会高于95%"
      },
      {
        "start": 131.6,
        "end": 134.04,
        "text": "这也是我最新心念念的一个指标"
      },
      {
        "start": 134.04,
        "end": 136.2,
        "text": "尤其是我现在还是天天在看"
      },
      {
        "start": 136.2,
        "end": 139.2,
        "text": "每期视频发布以后的3到4个小时"
      },
      {
        "start": 139.2,
        "end": 140.2,
        "text": "如果在这段时间里面"
      },
      {
        "start": 140.2,
        "end": 142.4,
        "text": "这个推进业的占比居然还没有办法达到"
      },
      {
        "start": 142.4,
        "end": 143.8,
        "text": "80%以上的话"
      },
      {
        "start": 143.8,
        "end": 145.6,
        "text": "那我这个时候心里就会打突了"
      },
      {
        "start": 145.6,
        "end": 148,
        "text": "那么大概率于这个作品就是有问题的"
      },
      {
        "start": 148,
        "end": 150.2,
        "text": "然后他给他表演然后重新发布吧"
      },
      {
        "start": 150.2,
        "end": 153,
        "text": "第二个很重要的指标就是粉丝播放占比"
      },
      {
        "start": 153,
        "end": 155.6,
        "text": "这个时候就会有个反直觉的现象出现了"
      },
      {
        "start": 155.6,
        "end": 156.6,
        "text": "就是大家会不会觉得"
      },
      {
        "start": 156.6,
        "end": 158.8,
        "text": "粉丝播放的占比越高越好"
      },
      {
        "start": 158.8,
        "end": 160.6,
        "text": "因为这样子你的所有粉丝都可以看到"
      },
      {
        "start": 160.6,
        "end": 161.8,
        "text": "那一个互动就会很高"
      },
      {
        "start": 161.8,
        "end": 163.2,
        "text": "谁想不是这样子的"
      },
      {
        "start": 163.2,
        "end": 165.8,
        "text": "在你作品发布的头一两天的时间里面"
      },
      {
        "start": 165.8,
        "end": 168.8,
        "text": "如果你的粉丝播放占比是大于30%的说明什么"
      },
      {
        "start": 168.8,
        "end": 170,
        "text": "就说明你的作品"
      },
      {
        "start": 170,
        "end": 172,
        "text": "几乎只推给了你的粉丝"
      },
      {
        "start": 172,
        "end": 174.8,
        "text": "而没有向外部的人群进行推流"
      },
      {
        "start": 174.8,
        "end": 178.4,
        "text": "那大家想想看作品只推给粉丝"
      },
      {
        "start": 178.4,
        "end": 179.4,
        "text": "当然我很开心"
      },
      {
        "start": 179.4,
        "end": 181.2,
        "text": "我的粉丝朋友们能够看到我的作品"
      },
      {
        "start": 181.2,
        "end": 183.8,
        "text": "但是很可惜从数据上会出现一个什么情况"
      },
      {
        "start": 183.8,
        "end": 186,
        "text": "你只会出现掉粉的一个情况"
      },
      {
        "start": 186,
        "end": 187.8,
        "text": "不会出现新增的粉丝"
      },
      {
        "start": 187.8,
        "end": 189.8,
        "text": "所以我刚才说的这两个指标"
      },
      {
        "start": 189.8,
        "end": 191.4,
        "text": "都是你作品的几个线"
      },
      {
        "start": 191.4,
        "end": 192.8,
        "text": "如果说这两个指标都不合格的话"
      },
      {
        "start": 192.8,
        "end": 194.2,
        "text": "那你的作品都不要说会起"
      },
      {
        "start": 194.2,
        "end": 195.4,
        "text": "否则会爆流量"
      },
      {
        "start": 195.4,
        "end": 197,
        "text": "它肯定是连基础的播放"
      },
      {
        "start": 197,
        "end": 199.4,
        "text": "就是一两千的播放都不可能达到的"
      },
      {
        "start": 199.4,
        "end": 199.8,
        "text": "OK"
      },
      {
        "start": 199.8,
        "end": 201,
        "text": "那么接下来我比较说说"
      },
      {
        "start": 201,
        "end": 202.6,
        "text": "如果这两个指标正常"
      },
      {
        "start": 202.6,
        "end": 204.8,
        "text": "你已经卖出了第一步哪些数据"
      },
      {
        "start": 204.8,
        "end": 206.6,
        "text": "能够决定你的视频能够走得更远"
      },
      {
        "start": 206.6,
        "end": 207.6,
        "text": "能够爆呢"
      },
      {
        "start": 207.6,
        "end": 208.8,
        "text": "那么在现代这个时间节点"
      },
      {
        "start": 208.8,
        "end": 211.2,
        "text": "我认为5秒玩波率和2秒跳出率"
      },
      {
        "start": 211.2,
        "end": 212.4,
        "text": "重不重要"
      },
      {
        "start": 212.4,
        "end": 213.4,
        "text": "重要还是重要的"
      },
      {
        "start": 213.4,
        "end": 216.4,
        "text": "但是它并不是原来的那种智观生死的数据"
      },
      {
        "start": 216.4,
        "end": 218,
        "text": "在我看来你的5秒玩波率"
      },
      {
        "start": 218,
        "end": 219.6,
        "text": "只要超过了35%"
      },
      {
        "start": 219.6,
        "end": 220.8,
        "text": "或者说你的2秒跳出率"
      },
      {
        "start": 220.8,
        "end": 222.8,
        "text": "能够低于35%的线"
      },
      {
        "start": 222.8,
        "end": 224.4,
        "text": "它就是一个达票的作品"
      },
      {
        "start": 224.4,
        "end": 225.8,
        "text": "更重要的是什么呢"
      },
      {
        "start": 225.8,
        "end": 227.2,
        "text": "实际上不是这两数据"
      },
      {
        "start": 227.2,
        "end": 228.6,
        "text": "而是以下的几个指标"
      },
      {
        "start": 228.6,
        "end": 229.4,
        "text": "第一个"
      },
      {
        "start": 229.4,
        "end": 231.2,
        "text": "平均播放占皮"
      },
      {
        "start": 231.2,
        "end": 233.8,
        "text": "这是取代玩波率的一个更重要的指标"
      },
      {
        "start": 233.8,
        "end": 235.6,
        "text": "就是用户观看你视频的市场"
      },
      {
        "start": 235.6,
        "end": 237.8,
        "text": "再除意你视频的一个总市场"
      },
      {
        "start": 237.8,
        "end": 239.6,
        "text": "比如说你是一个五分钟的视频"
      },
      {
        "start": 239.6,
        "end": 241.2,
        "text": "然后用户平均指观看一分钟"
      },
      {
        "start": 241.2,
        "end": 243.2,
        "text": "那么你的平均播放上比就是20%"
      },
      {
        "start": 243.2,
        "end": 244.8,
        "text": "那这个指标上比起玩波率"
      },
      {
        "start": 244.8,
        "end": 248.2,
        "text": "更能证明你的视频对观众是有吸引力的"
      },
      {
        "start": 248.2,
        "end": 250.4,
        "text": "因为现有观众是能真正玩波"
      },
      {
        "start": 250.4,
        "end": 251.6,
        "text": "能够看满你的视频的"
      },
      {
        "start": 251.6,
        "end": 252.8,
        "text": "所以这个玩波率"
      },
      {
        "start": 252.8,
        "end": 254.6,
        "text": "实际上他是不太做数的"
      },
      {
        "start": 254.6,
        "end": 255.8,
        "text": "但明白我的意思吧"
      },
      {
        "start": 255.8,
        "end": 257,
        "text": "你的视频越长的话"
      },
      {
        "start": 257,
        "end": 258.6,
        "text": "这个指标的及格线"
      },
      {
        "start": 258.6,
        "end": 259.8,
        "text": "它实际上也就越低"
      },
      {
        "start": 259.8,
        "end": 262,
        "text": "如果是五到十分钟的视频的平均播放上比能"
      },
      {
        "start": 262,
        "end": 263.6,
        "text": "在百分之八到百分之十的话"
      },
      {
        "start": 263.6,
        "end": 265.2,
        "text": "那这就是一个非常不错的指标"
      },
      {
        "start": 265.2,
        "end": 267,
        "text": "但如果你就是一个一分钟的视频"
      },
      {
        "start": 267,
        "end": 268.2,
        "text": "那这个数据就应该要再搞"
      },
      {
